// Synchronization Service - Handles data sync between offline and online states
import { 
  db, 
  getPendingSyncOperations, 
  completeSyncOperation, 
  failSyncOperation,
  getUnprocessedOfflineActions,
  markOfflineActionProcessed,
  getRecordsNeedingSync,
  markRecordSynced,
  updateSyncTimestamp,
  exportDataForSync,
  importDataFromSync
} from './database.js';

class SyncService {
  constructor() {
    this.isOnline = navigator.onLine;
    this.syncInProgress = false;
    this.syncListeners = new Set();
    this.lastSyncTime = null;
    this.syncInterval = null;
    this.retryTimeout = null;
    
    this.init();
  }

  init() {
    // Listen for online/offline events
    window.addEventListener('online', this.handleOnline.bind(this));
    window.addEventListener('offline', this.handleOffline.bind(this));
    
    // Start periodic sync when online
    if (this.isOnline) {
      this.startPeriodicSync();
    }
    
    // Load last sync time
    this.loadLastSyncTime();
  }

  // Event handlers
  handleOnline() {
    console.log('SyncService: Device is online');
    this.isOnline = true;
    this.notifyListeners('online');
    
    // Start sync process
    this.startSync();
    this.startPeriodicSync();
  }

  handleOffline() {
    console.log('SyncService: Device is offline');
    this.isOnline = false;
    this.notifyListeners('offline');
    
    // Stop periodic sync
    this.stopPeriodicSync();
  }

  // Listener management
  addSyncListener(callback) {
    this.syncListeners.add(callback);
    return () => this.syncListeners.delete(callback);
  }

  notifyListeners(event, data = null) {
    this.syncListeners.forEach(callback => {
      try {
        callback({
          event,
          data,
          isOnline: this.isOnline,
          syncInProgress: this.syncInProgress,
          lastSyncTime: this.lastSyncTime
        });
      } catch (error) {
        console.error('SyncService: Listener error:', error);
      }
    });
  }

  // Sync management
  async startSync() {
    if (!this.isOnline || this.syncInProgress) {
      return;
    }

    this.syncInProgress = true;
    this.notifyListeners('sync-start');
    
    try {
      await updateSyncTimestamp('last_sync_attempt');
      
      // Step 1: Process pending sync operations
      await this.processPendingSyncOperations();
      
      // Step 2: Sync records that need syncing
      await this.syncPendingRecords();
      
      // Step 3: Process offline actions
      await this.processOfflineActions();
      
      // Step 4: Fetch latest data from server (if applicable)
      await this.fetchLatestData();
      
      this.lastSyncTime = new Date();
      await updateSyncTimestamp('last_successful_sync', this.lastSyncTime);
      
      this.notifyListeners('sync-success', {
        syncTime: this.lastSyncTime
      });
      
      console.log('SyncService: Sync completed successfully');
      
    } catch (error) {
      console.error('SyncService: Sync failed:', error);
      this.notifyListeners('sync-error', {
        error: error.message
      });
      
      // Schedule retry
      this.scheduleRetry();
      
    } finally {
      this.syncInProgress = false;
      this.notifyListeners('sync-end');
    }
  }

  // Process pending sync operations from the queue
  async processPendingSyncOperations() {
    const operations = await getPendingSyncOperations();
    console.log(`SyncService: Processing ${operations.length} pending operations`);
    
    for (const operation of operations) {
      try {
        await this.executeOperation(operation);
        await completeSyncOperation(operation.id);
        console.log(`SyncService: Completed operation ${operation.id}`);
        
      } catch (error) {
        console.error(`SyncService: Operation ${operation.id} failed:`, error);
        await failSyncOperation(operation.id, error.message);
      }
    }
  }

  // Execute a specific sync operation
  async executeOperation(operation) {
    const { table_name, record_id, operation: op, data } = operation;
    
    switch (op) {
      case 'create':
        return await this.createRecord(table_name, data);
      
      case 'update':
        return await this.updateRecord(table_name, record_id, data);
      
      case 'delete':
        return await this.deleteRecord(table_name, record_id);
      
      default:
        throw new Error(`Unknown operation: ${op}`);
    }
  }

  // API operations (these would connect to your actual backend)
  async createRecord(tableName, data) {
    // Simulate API call - replace with actual endpoint
    const response = await fetch(`/api/${tableName}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(data)
    });
    
    if (!response.ok) {
      throw new Error(`Failed to create ${tableName}: ${response.statusText}`);
    }
    
    return await response.json();
  }

  async updateRecord(tableName, recordId, data) {
    // Simulate API call - replace with actual endpoint
    const response = await fetch(`/api/${tableName}/${recordId}`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(data)
    });
    
    if (!response.ok) {
      throw new Error(`Failed to update ${tableName}/${recordId}: ${response.statusText}`);
    }
    
    return await response.json();
  }

  async deleteRecord(tableName, recordId) {
    // Simulate API call - replace with actual endpoint
    const response = await fetch(`/api/${tableName}/${recordId}`, {
      method: 'DELETE'
    });
    
    if (!response.ok) {
      throw new Error(`Failed to delete ${tableName}/${recordId}: ${response.statusText}`);
    }
    
    return true;
  }

  // Sync records that have pending status
  async syncPendingRecords() {
    const records = await getRecordsNeedingSync();
    console.log(`SyncService: Syncing ${records.total} pending records`);
    
    // Sync initiatives
    for (const initiative of records.initiatives) {
      try {
        if (initiative.sync_status === 'pending_delete') {
          await this.deleteRecord('initiatives', initiative.id);
          await db.initiatives.delete(initiative.id);
        } else {
          await this.updateRecord('initiatives', initiative.id, initiative);
          await markRecordSynced('initiatives', initiative.id);
        }
      } catch (error) {
        console.error(`Failed to sync initiative ${initiative.id}:`, error);
      }
    }
    
    // Sync award points
    for (const awardPoint of records.awardPoints) {
      try {
        if (awardPoint.sync_status === 'pending_delete') {
          await this.deleteRecord('awardPoints', awardPoint.id);
          await db.awardPoints.delete(awardPoint.id);
        } else {
          await this.updateRecord('awardPoints', awardPoint.id, awardPoint);
          await markRecordSynced('awardPoints', awardPoint.id);
        }
      } catch (error) {
        console.error(`Failed to sync award point ${awardPoint.id}:`, error);
      }
    }
    
    // Sync departments
    for (const department of records.departments) {
      try {
        if (department.sync_status === 'pending_delete') {
          await this.deleteRecord('departments', department.id);
          await db.departments.delete(department.id);
        } else {
          await this.updateRecord('departments', department.id, department);
          await markRecordSynced('departments', department.id);
        }
      } catch (error) {
        console.error(`Failed to sync department ${department.id}:`, error);
      }
    }
  }

  // Process offline actions
  async processOfflineActions() {
    const actions = await getUnprocessedOfflineActions();
    console.log(`SyncService: Processing ${actions.length} offline actions`);
    
    for (const action of actions) {
      try {
        await this.processOfflineAction(action);
        await markOfflineActionProcessed(action.id);
      } catch (error) {
        console.error(`Failed to process offline action ${action.id}:`, error);
      }
    }
  }

  // Process a specific offline action
  async processOfflineAction(action) {
    const { action_type, data } = action;
    
    switch (action_type) {
      case 'add_initiative':
      case 'update_initiative':
      case 'delete_initiative':
        // These are handled by sync operations
        break;
        
      case 'add_award_point':
      case 'update_award_point':
      case 'delete_award_point':
        // These are handled by sync operations
        break;
        
      case 'export_data':
        await this.handleDataExport(data);
        break;
        
      case 'import_data':
        await this.handleDataImport(data);
        break;
        
      default:
        console.warn(`Unknown offline action: ${action_type}`);
    }
  }

  // Fetch latest data from server
  async fetchLatestData() {
    try {
      // This would fetch the latest data from your server
      // For now, we'll skip this as we don't have a backend
      console.log('SyncService: Fetching latest data (simulated)');
      
      // Example of how this might work:
      // const response = await fetch('/api/sync/latest');
      // const latestData = await response.json();
      // await importDataFromSync(latestData);
      
    } catch (error) {
      console.warn('SyncService: Failed to fetch latest data:', error);
    }
  }

  // Handle data export
  async handleDataExport(data) {
    const exportData = await exportDataForSync();
    
    // Send to server or save to file
    console.log('SyncService: Data export completed', exportData);
    
    // You could send this to a server endpoint:
    // await fetch('/api/backup', {
    //   method: 'POST',
    //   headers: { 'Content-Type': 'application/json' },
    //   body: JSON.stringify(exportData)
    // });
  }

  // Handle data import
  async handleDataImport(data) {
    await importDataFromSync(data);
    console.log('SyncService: Data import completed');
  }

  // Periodic sync
  startPeriodicSync() {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
    }
    
    // Sync every 5 minutes when online
    this.syncInterval = setInterval(() => {
      if (this.isOnline && !this.syncInProgress) {
        this.startSync();
      }
    }, 5 * 60 * 1000);
  }

  stopPeriodicSync() {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
      this.syncInterval = null;
    }
  }

  // Retry mechanism
  scheduleRetry() {
    if (this.retryTimeout) {
      clearTimeout(this.retryTimeout);
    }
    
    // Retry after 30 seconds
    this.retryTimeout = setTimeout(() => {
      if (this.isOnline) {
        console.log('SyncService: Retrying sync...');
        this.startSync();
      }
    }, 30000);
  }

  // Manual sync trigger
  async forceSync() {
    if (!this.isOnline) {
      throw new Error('Cannot sync while offline');
    }
    
    await this.startSync();
  }

  // Get sync status
  getSyncStatus() {
    return {
      isOnline: this.isOnline,
      syncInProgress: this.syncInProgress,
      lastSyncTime: this.lastSyncTime
    };
  }

  // Load last sync time from storage
  async loadLastSyncTime() {
    try {
      const lastSync = localStorage.getItem('last_sync_time');
      if (lastSync) {
        this.lastSyncTime = new Date(lastSync);
      }
    } catch (error) {
      console.error('Failed to load last sync time:', error);
    }
  }

  // Cleanup
  destroy() {
    window.removeEventListener('online', this.handleOnline);
    window.removeEventListener('offline', this.handleOffline);
    this.stopPeriodicSync();
    
    if (this.retryTimeout) {
      clearTimeout(this.retryTimeout);
    }
    
    this.syncListeners.clear();
  }
}

// Create singleton instance
export const syncService = new SyncService();

// Export class for testing
export { SyncService };

// Utility functions
export const startSync = () => syncService.startSync();
export const forceSync = () => syncService.forceSync();
export const addSyncListener = (callback) => syncService.addSyncListener(callback);
export const getSyncStatus = () => syncService.getSyncStatus();
